    std::uint8_t *aKeyRow = &(pWorkSpace->mKeyBoxB[0][0]);

    static_assert(S_BLOCK == 32768, "Key folding requires 32,768-byte lanes.");
    static_assert(W_KEY == 2048, "Key folding requires 2,048-byte key rows.");

